stylesheet:
/* Hoja de estilos dinámica generada por ThemeEngine de Escritorio */
QMainWindow, QWidget#root {
    background-color: #18191A;
    color: #E4E6EB;
    font-family: 'Segoe UI Variable Display', 'Segoe UI', -apple-system, sans-serif;
    font-size: 11px;
}

/* Barra de herramientas compacta (28px) */
QToolBar#mainToolbar {
    background-color: #202124;
    color: #E4E6EB;
    border-bottom: 1px solid #2E3033;
    min-height: 28px;
    max-height: 28px;
    padding: 0 4px;
}
QToolBar#mainToolbar QToolButton {
    font-size: 10px;
    height: 22px;
    padding: 2px 6px;
    border-radius: 3px;
}
QToolBar#mainToolbar QToolButton:hover {
    background-color: #2D3748;
}

/* Binder / Navegador jerárquico */
QTreeView#binder {
    background-color: #18191A;
    color: #E4E6EB;
    border: none;
    border-right: 1px solid #2E3033;
    font-size: 11px;
}
QTreeView#binder::item {
    height: 22px;
}
QTreeView#binder::item:selected {
    background-color: #2D3748;
    color: #FFFFFF;
    border-radius: 3px;
}

/* Cabecera del Editor (24px) */
QWidget#editorHeader {
    background-color: #1C1D20;
    color: #B0B3B8;
    min-height: 24px;
    max-height: 24px;
    border-bottom: 1px solid #2E3033;
    font-size: 10px;
}

/* Editor RTF */
QTextEdit#editor {
    background-color: #141517;
    color: #E4E6EB;
    selection-background-color: #2C3E50;
    border: none;
    font-family: 'Georgia', 'Segoe UI Variable Text', serif;
}

/* Pizarra de Corcho (Corkboard) */
QWidget#corkboard {
    background-color: #1C1D1F;
}
QWidget#corkboardCard {
    background-color: #25272A;
    color: #E4E6EB;
    border: 1px solid #36383D;
    border-radius: 4px;
}

/* Esquematizador (Outliner) */
QTableView#outliner {
    background-color: #18191A;
    color: #E4E6EB;
    gridline-color: #2E3033;
    border: none;
}
QTableView#outliner::item:alternate {
    background-color: #1C1D20;
}

/* Inspector Lateral */
QDockWidget#inspector {
    background-color: #18191A;
    color: #E4E6EB;
    border-left: 1px solid #2E3033;
}
QWidget#inspectorCard {
    background-color: #25272A;
    border: 1px solid #2E3033;
    border-radius: 4px;
}

/* Barra de estado */
QStatusBar#statusBar {
    background-color: #141517;
    color: #B0B3B8;
    border-top: 1px solid #2E3033;
    min-height: 22px;
    font-size: 10px;
}

/* Micro-etiquetas y badges */
QLabel.microBadge {
    font-size: 9px;
    font-weight: bold;
    padding: 1px 4px;
    border-radius: 5px;
    background-color: #1E3A8A;
    color: #BFDBFE;
}
